  line-height: 1.5;
  min-height: 100dvh;
}

/* ─── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  inset-block-start: -100%;
  inset-inline-start: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: inset-block-start var(--transition);
}
.skip-link:focus {
  inset-block-start: 1rem;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

