  display: flex;
  flex-direction: column;
}

.preview-image {
  display: block;
  width: 100%;
  max-height: 480px;
  object-fit: cover;
  object-position: center;
  background: var(--bg-page);
}

.image-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--border);
}

.image-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.2rem;
}

.image-details {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 0.75rem;
  font-size: 0.8125rem;
  color: var(--text-secondary);
