+  padding: 2.5rem 1rem 4rem;
+}
+
+.preview-section {
+  width: 100%;
+  max-width: 780px;
+}
+
+/* ─── Image card ─────────────────────────────────────────────── */
+.image-card {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  box-shadow: var(--shadow-card);
+}
+
+.image-figure {
+  display: flex;
+  flex-direction: column;
+}
+
+.preview-image {
+  display: block;
+  width: 100%;
+  max-height: 480px;
+  object-fit: cover;
+  object-position: center;
+  background: var(--bg-page);
+}
+
+.image-meta {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 1rem;
+  padding: 1.25rem 1.5rem;
+  border-top: 1px solid var(--border);
+}
+
+.image-title {
+  font-size: 1.05rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  margin-bottom: 0.2rem;
+}
+
+.image-details {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.4rem 0.75rem;
+  font-size: 0.8125rem;
+  color: var(--text-secondary);
+}
+
+.image-actions {
+  display: flex;
+  gap: 0.625rem;
+  flex-shrink: 0;
+}
+
+/* ─── Buttons ────────────────────────────────────────────────── */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.45rem;
+  padding: 0.5rem 1rem;
+  border: 1px solid transparent;
+  border-radius: var(--radius-sm);
+  font-size: 0.875rem;
+  font-weight: 500;
+  cursor: pointer;
+  transition: background var(--transition), color var(--transition),
+              border-color var(--transition), box-shadow var(--transition);
+  white-space: nowrap;
+  text-decoration: none;
+}
+
+.btn:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 2px;
+}
+
+/* Secondary (download) */
+.btn-secondary {
+  background: transparent;
+  color: var(--text-primary);
+  border-color: var(--border);
+}
+.btn-secondary:hover {
+  background: var(--bg-card-hover);
+  border-color: #3a3f50;
+}
+
+/* Danger outlined (trigger) */
+.btn-danger {
+  background: var(--danger-bg);
+  color: var(--danger);
+  border-color: rgba(255, 90, 90, 0.3);
+}
+.btn-danger:hover {
+  background: var(--danger-bg-hover);
+  border-color: rgba(255, 90, 90, 0.5);
+}
+
+/* Ghost (cancel inside modal) */
+.btn-ghost {
+  background: transparent;
+  color: var(--text-secondary);
+  border-color: var(--border);
+}
+.btn-ghost:hover {
+  background: var(--bg-card-hover);
+  color: var(--text-primary);
+  border-color: #3a3f50;
+}
+
+/* Danger solid (confirm delete) */
+.btn-danger-solid {
+  background: var(--danger-solid);
+  color: #fff;
+  border-color: transparent;
+}
+.btn-danger-solid:hover {
+  background: var(--danger-solid-hover);
+}
+
+/* Forced-colors support */
+@media (forced-colors: active) {
+  .btn {
+    border: 2px solid ButtonBorder;
+    color: ButtonText;
+    background: ButtonFace;
+    forced-color-adjust: auto;
+  }
+  .btn-danger-solid {
+    background: Highlight;
+    color: HighlightText;
+  }
+}
+
+/* ─── Modal backdrop + dialog ────────────────────────────────── */
+dialog.modal {
+  /* Reset browser defaults */
+  border: none;
+  padding: 0;
+  background: transparent;
+
+  /* Sizing */
+  width: min(480px, calc(100vw - 2rem));
+  max-height: calc(100dvh - 4rem);
+  overflow: visible;
+
+  /* Centering via inset */
+  position: fixed;
+  inset: 0;
+  margin: auto;
+
+  /* Hidden by default — toggled via JS */
+  display: none;
+}
+
+/* Native <dialog> open state */
+dialog.modal[open] {
+  display: block;
+}
+
+/* Backdrop via ::backdrop */
+dialog.modal::backdrop {
+  background: var(--bg-overlay);
+  backdrop-filter: blur(3px);
+  -webkit-backdrop-filter: blur(3px);
+}
+
+/* Inner card */
+.modal-inner {
+  position: relative;
+  background: var(--bg-modal);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 2rem;
+  box-shadow: var(--shadow-modal);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  text-align: center;
+  gap: 0.75rem;
+}
+
+/* Danger icon circle */
+.modal-icon {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 56px;
+  height: 56px;
+  border-radius: 50%;
+  background: var(--danger-bg);
+  color: var(--icon-danger);
+  margin-bottom: 0.25rem;
+  flex-shrink: 0;
+}
+
+.modal-title {
+  font-size: 1.2rem;
+  font-weight: 700;
+  color: var(--text-primary);
+  line-height: 1.3;
+}
+
+.modal-desc {
+  font-size: 0.9rem;
+  color: var(--text-secondary);
+  max-width: 340px;
+  line-height: 1.6;
+}
+
+.modal-desc strong {
+  color: var(--text-primary);
+  font-weight: 600;
+}
+
+.modal-actions {
+  display: flex;
+  gap: 0.625rem;
+  justify-content: center;
+  flex-wrap: wrap;
+  margin-top: 0.5rem;
+  width: 100%;
+}
+
+.modal-actions .btn {
+  flex: 1 1 120px;
+  justify-content: center;
+}
+
+/* Close (×) button in top-right */
+.modal-close {
+  position: absolute;
+  top: 0.875rem;
+  right: 0.875rem;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 32px;
+  height: 32px;
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  background: transparent;
+  color: var(--text-muted);
+  cursor: pointer;
+  transition: background var(--transition), color var(--transition),
+              border-color var(--transition);
+  padding: 0;
+}
+.modal-close:hover {
+  background: var(--bg-card-hover);
+  color: var(--text-primary);
+  border-color: #3a3f50;
+}
+.modal-close:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: 2px;
+}
+
+/* ─── Reflow at 320 px ───────────────────────────────────────── */
+@media (max-width: 480px) {
+  .image-meta {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+  .image-actions {
+    width: 100%;
+  }
+  .image-actions .btn {
+    flex: 1;
+    justify-content: center;
+  }
+  .modal-inner {
+    padding: 1.5rem 1.25rem;
+  }
+}
+
')

